  try {
    const d = new Date(new Date(msg.data_hora).getTime() - 3 * 60 * 60 * 1000);
    hora = d.toISOString().substring(11, 16);
    data = d.toISOString().substring(8, 10) + '/' + d.toISOString().substring(5, 7);
  } catch(e) {}

  const prefixo = (reportType === 'semanal' || reportType === 'mensal') ? `[${data} ${hora}]` : `[${hora}]`;
  const tipo = msg.tipo_atendimento || '';
  const tipoTag = tipo === 'solicitacao' ? ' 🔴' : tipo === 'resolucao' ? ' ✅' : '';
  const linha = `${prefixo} ${msg.remetente}: ${msg.mensagem}${tipoTag}`;
  historico += linha + '\n';

  if (tipo === 'solicitacao') {
    solicitacoes.push(`${prefixo} ${msg.remetente}: ${(msg.mensagem || '').substring(0, 200)}`);
  } else if (tipo === 'resolucao') {
    resolucoes.push(`${prefixo} ${msg.remetente}: ${(msg.mensagem || '').substring(0, 200)}`);
  } else {
    outrasMsg++;
  }
}

let resumoStats = `\n\n📊 ESTATÍSTICAS PRÉ-CALCULADAS (DADOS EXATOS - NÃO RECONTE):\n- Total de mensagens no período: ${totalMsgs}\n- Solicitações de serviço detectadas: ${solicitacoes.length}\n- Resoluções/conclusões detectadas: ${resolucoes.length}\n- Mensagens gerais (conversa): ${outrasMsg}\n`;

if (solicitacoes.length > 0) {
