  imagens = detecta.allImages;
} else if (detecta.preloadedBase64) {
  imagens = [{ base64: detecta.preloadedBase64, mimetype: detecta.preloadedMimetype }];
} else if (upstream.base64) {
  imagens = [{ base64: upstream.base64, mimetype: (upstream.mimetype || 'image/jpeg').split(';')[0] }];
}

const caption = detecta.caption || '';
const total = imagens.length;

const systemPrompt = total > 1
  ? 'Você analisa grupos de imagens enviadas por técnicos de uma provedora de internet (Zazz) ou prints de conversas. Descreva em 3-6 frases CURTAS o conjunto, considerando a SEQUÊNCIA das imagens quando relevante (ex: fluxo de uma conversa de WhatsApp, etapas de um problema). Se houver texto legível, transcreva os trechos mais relevantes entre aspas. Não use emojis. Apenas a descrição, sem preâmbulo.'
  : 'Você descreve imagens de um grupo de WhatsApp de técnicos de uma provedora de internet (Zazz). Descreva em 1-3 frases CURTAS o que aparece. Se houver texto legível (placa, documento, screenshot), transcreva entre aspas. Se for equipamento/infraestrutura de rede (OLT, ONU, poste, cabo, conector), identifique. Não use emojis. Apenas a descrição, sem preâmbulo.';

const userPromptText = caption
  ? (total > 1
      ? `Legenda do usuário: "${caption}". Descreva o conjunto de ${total} imagens considerando essa legenda.`
      : `Legenda do usuário: "${caption}". Descreva a imagem considerando essa legenda.`)
  : (total > 1 ? `Descreva o conjunto de ${total} imagens.` : 'Descreva a imagem.');

const contentArr = imagens.map((img, i) => ({
  type: 'image',
  source: { type: 'base64', media_type: img.mimetype || 'image/jpeg', data: img.base64 }
}));
contentArr.push({ type: 'text', text: userPromptText });

const bodyObj = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: total > 1 ? 600 : 300,
  system: systemPrompt,
  messages: [{ role: 'user', content: contentArr }]
};

return [{ json: {
  body: JSON.stringify(bodyObj),
  base64: imagens[0]?.base64 || '',
  mimetype: imagens[0]?.mimetype || 'image/jpeg',
  caption,
  allImages: imagens,
  totalImages: total
} }];
